//! Real same-Db/source-domain ALLOW validation; no whole-unused completion.
use super::*;
use dq_analyze::captured_reactive_reads::Failure;
fn allow_fixture(label:&str,count:usize)->PathBuf{let root=fixture(label,count);std::fs::create_dir(root.join("maps")).unwrap();std::fs::create_dir(root.join("code/exempt")).unwrap();std::fs::write(root.join("maps/probe.dm"),"// ALLOW(capture_custom): world.Export() is a blocking external call\n").unwrap();std::fs::write(root.join("code/exempt/probe.dm"),"// ALLOW(@): must be excluded through the actual captured scope\n").unwrap();std::fs::write(root.join("lint_scopes.toml"),"[allow]\nknown=[\"capture_custom\"]\n[lint.allow_annotations]\nexempt_prefixes=[\"code/exempt/\"]\n").unwrap();std::fs::write(root.join("code/0000.dm"),"/proc/probe()\n    return\n// ALLOW(keys, capture_custom): actual captured configuration supplies this explicit namespace\n").unwrap();if count>1{std::fs::write(root.join("code/0001.dm"),"// ALLOW(not_a_real_lint): world.Export() is a blocking external call\n// ALLOW():\n// ALLOW(sys_update_icon): see above for the actual reason for this operation\n// ALLOW(@): malformed annotation\n").unwrap();}root}
fn allow_capture<P:SnapshotProvider>(root:&Path,front:&ColdFrontend,inputs:&RecordingInputs<P>)->Arc<workspace_capture::WorkspaceCapture>{let discovery=Arc::new(workspace_discovery::discover(inputs,DiscoveryContract{root:root.into(),recursive_roots:vec![root.join("code"),root.join("maps")]}).unwrap());workspace_capture::capture(front,inputs,discovery,&root.join("lint_scopes.toml")).unwrap()}
fn fingerprint(snapshot:&SourceSnapshot)->Result<(u128,usize),Failure>{snapshot.with_native_allow_annotations(&snapshot.tree,|output,_,_|{let mut hash=xxhash_rust::xxh3::Xxh3::new();for(site,text)in output.sites.iter().zip(&output.source_text){for value in[site.rule.as_str(),site.rel.as_str(),site.msg.as_str(),text.as_str()]{hash.update(&(value.len()as u64).to_le_bytes());hash.update(value.as_bytes());}hash.update(&site.line.to_le_bytes());}Ok((hash.digest128(),output.sites.len()))})}
#[test]fn actual_allow_annotations_full_source_config_and_nonraw_registry_names_no_io_or_body_queries(){
 let root=allow_fixture("allow-real-source-129",129);let db=Arc::new(crate::query_db::QueryDb::default());let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(None)};let inputs=RecordingInputs::new(&physical,4_000_000_000);let front=frontend(&root,&inputs,&db);let capture=allow_capture(&root,&front,&inputs);let snapshot=snapshot(&front,&db,&inputs,&capture);let before=physical.reads();
 snapshot.with_native_allow_annotations(&snapshot.tree,|data,_,_|{let rows=data.sites.iter().map(|site|(site.rule.as_str(),site.rel.as_str(),site.line)).collect::<Vec<_>>();assert_eq!(rows,vec![("unknown_lint","code/0001.dm",1),("no_lint","code/0001.dm",2),("no_reason","code/0001.dm",2),("weak_reason","code/0001.dm",3),("malformed","code/0001.dm",4)]);assert!(data.sites[0].msg.contains("capture_custom"));assert!(data.sites[0].msg.contains("sys_update_icon"));assert_eq!(data.source_text.len(),data.sites.len());assert!(data.source_text[0].contains("not_a_real_lint"));Ok(())}).unwrap();let first=fingerprint(&snapshot).unwrap();assert_eq!(first.1,5);assert_eq!(fingerprint(&snapshot).unwrap(),first);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);assert_eq!(physical.reads(),before);
 std::fs::write(root.join("lint_scopes.toml"),"[allow]\nknown=[]\n").unwrap();std::fs::write(root.join("code/0001.dm"),"// changed after immutable source admission\n").unwrap();assert_eq!(fingerprint(&snapshot).unwrap(),first,"as-of source/config observations remain unchanged without a filesystem reread");assert_eq!(physical.reads(),before);
}
#[test]fn actual_allow_annotations_refuses_partial_foreign_and_preserves_1450_cancel_unwind_quota_recovery(){
 let root=allow_fixture("allow-real-controls",2);let db=Arc::new(crate::query_db::QueryDb::default());let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(None)};let inputs=RecordingInputs::new(&physical,4_000_000_000);let front=frontend(&root,&inputs,&db);let capture=allow_capture(&root,&front,&inputs);let snapshot=snapshot(&front,&db,&inputs,&capture);let guard=snapshot.workspace_native_read().unwrap();let before=physical.reads();let entered=std::cell::Cell::new(0);let foreign=crate::query_db::QueryDb::default();assert!(foreign.with_workspace_allow_annotations(&capture,&guard,|_,_,_|{entered.set(entered.get()+1);Ok(())}).is_err());assert_eq!(entered.get(),0);
 let tiny=db.with_workspace_allow_annotations_limit(&capture,&guard,128,|_,_,_|{entered.set(entered.get()+1);Ok(())});assert!(matches!(tiny,Err(Failure::Operational(ref error))if error.kind()==io::ErrorKind::OutOfMemory));assert_eq!(entered.get(),0);let first=fingerprint(&snapshot).unwrap();
 let token=crate::daemon::control::Cancellation::default();let bound=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(30));let error=snapshot.with_native_allow_annotations(&snapshot.tree,|_,_,_|{token.cancel();Err::<(),_>(io::Error::from_raw_os_error(1450))}).unwrap_err();assert!(matches!(error,Failure::Operational(ref error)if error.raw_os_error()==Some(1450)));drop(bound);assert_eq!(fingerprint(&snapshot).unwrap(),first);
 assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||snapshot.with_native_allow_annotations(&snapshot.tree,|_,_,_|->io::Result<()>{panic!("ALLOW actual consumer unwind control")}))).is_err());assert_eq!(fingerprint(&snapshot).unwrap(),first);assert_eq!(physical.reads(),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
 let partial_inputs=RecordingInputs::new(&physical,4_000_000_001);let partial_front=frontend(&root,&partial_inputs,&db);let partial_discovery=Arc::new(workspace_discovery::discover(&partial_inputs,DiscoveryContract{root:root.clone(),recursive_roots:vec![root.join("code")]}).unwrap());let partial=workspace_capture::capture(&partial_front,&partial_inputs,partial_discovery,&root.join("lint_scopes.toml")).unwrap();let partial_snapshot=super::snapshot(&partial_front,&db,&partial_inputs,&partial);assert!(partial_snapshot.with_native_allow_annotations(&partial_snapshot.tree,|_,_,_|{entered.set(entered.get()+1);Ok(())}).is_err());assert_eq!(entered.get(),0,"actual code-only discovery cannot seal CODE_MAPS_DM validation");
}
#[test]fn actual_allow_annotations_original_capture_io_remains_1450_and_fresh_recorder_recovers(){
 let root=allow_fixture("allow-real-source-io",2);let db=Arc::new(crate::query_db::QueryDb::default());let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(None)};let inputs=RecordingInputs::new(&physical,4_000_000_000);let front=frontend(&root,&inputs,&db);let discovery=Arc::new(workspace_discovery::discover(&inputs,DiscoveryContract{root:root.clone(),recursive_roots:vec![root.join("code"),root.join("maps")]}).unwrap());*physical.fail_policy.lock().unwrap()=Some(root.join("code/0001.dm"));let error=workspace_capture::capture(&front,&inputs,discovery,&root.join("lint_scopes.toml")).err().expect("actual source IO must refuse before snapshot publication");assert_eq!(error.raw_os_error(),Some(1450));*physical.fail_policy.lock().unwrap()=None;drop(front);drop(inputs);let fresh=RecordingInputs::new(&physical,4_000_000_001);let front=frontend(&root,&fresh,&db);let capture=allow_capture(&root,&front,&fresh);let snapshot=snapshot(&front,&db,&fresh,&capture);assert_eq!(fingerprint(&snapshot).unwrap().1,5);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}
